WITH openivm_net AS (
  SELECT token, island, flagged,
    SUM(openivm_multiplicity) AS _net
  FROM memory.main.openivm_delta___openivm_mv_6d656d6f7279_6d61696e_6e73635f70325f646e_ WHERE openivm_timestamp > CAST('2026-11-20 06:29:31.420038' AS TIMESTAMP)
  GROUP BY token, island, flagged
  HAVING SUM(openivm_multiplicity) != 0
)
, openivm_delete_net AS (
  SELECT * FROM openivm_net WHERE _net < 0
), openivm_delete_candidates AS (
  SELECT v.rowid, v.token AS token, v.island AS island, v.flagged AS flagged, d._net
  FROM memory.main.openivm_data___openivm_mv_6d656d6f7279_6d61696e_6e73635f70325f646e_ v JOIN openivm_delete_net d ON v.token <=> d.token AND v.island <=> d.island AND v.flagged <=> d.flagged
), openivm_ranked_deletes AS (
  SELECT rowid, _net,
    ROW_NUMBER() OVER (PARTITION BY token, island, flagged ORDER BY rowid) AS _rn
  FROM openivm_delete_candidates
)
DELETE FROM memory.main.openivm_data___openivm_mv_6d656d6f7279_6d61696e_6e73635f70325f646e_ WHERE rowid IN (
  SELECT rowid FROM openivm_ranked_deletes WHERE _rn <= -_net
);
